/*
 * Decodes one UTF-8 sequence. An invalid byte counts as U+FFFD, which is
 * what a JavaScript runtime would see in its place.
 */
static unsigned long utf8_next(const unsigned char **sp)
{
	const unsigned char *s = *sp;
	unsigned long cp, min;
	int len, i;

	if (s[0] < 0x80) {
		*sp = s + 1;
		return s[0];
	}
	if ((s[0] & 0xe0) == 0xc0) {
		len = 2;
		cp = s[0] & 0x1f;
		min = 0x80;
	} else if ((s[0] & 0xf0) == 0xe0) {
		len = 3;
		cp = s[0] & 0x0f;
		min = 0x800;
	} else if ((s[0] & 0xf8) == 0xf0) {
		len = 4;
		cp = s[0] & 0x07;
		min = 0x10000;
	} else {
		*sp = s + 1;
		return 0xfffd;
	}
	for (i = 1; i < len; i++) {
		if ((s[i] & 0xc0) != 0x80) {
			*sp = s + 1;
			return 0xfffd;
		}
		cp = cp << 6 | (s[i] & 0x3f);
	}
	if (cp < min || cp > 0x10ffff || (cp >= 0xd800 && cp <= 0xdfff)) {
		*sp = s + 1;
		return 0xfffd;
	}
	*sp = s + len;
	return cp;
}

static int is_ascii_alnum(unsigned long c)
{
	return (c >= '0' && c <= '9') || (c >= 'A' && c <= 'Z') ||
	    (c >= 'a' && c <= 'z');
}

/*
 * Claude Code works on UTF-16 code units: every unit outside [A-Za-z0-9]
 * becomes '-', so a character outside the BMP gives two dashes. Names
 * longer than PATH_ENCODE_MAX are cut and get the base-36 absolute value
 * of Java's String.hashCode of the original path.
 */
char *path_encode(const char *path)
{
	const unsigned char *s = (const unsigned char *)path;
	unsigned long cp, units[2], hash = 0;
	size_t n = 0;
	char *out, digits[16];
	int count, i, d;

	out = xmalloc(strlen(path) + sizeof digits + 2);
	while (*s != '\0') {
		cp = utf8_next(&s);
		if (cp >= 0x10000) {
			units[0] = 0xd800 + ((cp - 0x10000) >> 10);
			units[1] = 0xdc00 + ((cp - 0x10000) & 0x3ff);
			count = 2;
		} else {
			units[0] = cp;
			count = 1;
		}
		for (i = 0; i < count; i++) {
			hash = (hash * 31 + units[i]) & 0xffffffffUL;
			out[n++] = is_ascii_alnum(units[i]) ? (char)units[i] : '-';
		}
	}
	if (n > PATH_ENCODE_MAX) {
		if (hash & 0x80000000UL)
			hash = (0xffffffffUL - hash + 1) & 0xffffffffUL;
		d = 0;
		do {
			digits[d++] = "0123456789abcdefghijklmnopqrstuvwxyz"[hash % 36];
			hash /= 36;
		} while (hash != 0);
		n = PATH_ENCODE_MAX;
		out[n++] = '-';
		while (d > 0)
			out[n++] = digits[--d];
	}
	out[n] = '\0';
	return out;
}

/* Removes ".", ".." and repeated slashes without touching the file system. */
char *path_normalize(const char *path)
{
	const char *p, *end;
	size_t n = 0, len;
	char *out;

	out = xmalloc(strlen(path) + 2);
	for (p = path; *p != '\0'; p = end) {
		while (*p == '/')
			p++;
		for (end = p; *end != '\0' && *end != '/'; end++)
			;
		len = (size_t)(end - p);
		if (len == 0 || (len == 1 && p[0] == '.'))
			continue;
		if (len == 2 && p[0] == '.' && p[1] == '.') {
			while (n > 0 && out[n - 1] != '/')
				n--;
			if (n > 0)
				n--;
			continue;
		}
		out[n++] = '/';
		memcpy(out + n, p, len);
		n += len;
	}
	if (n == 0)
		out[n++] = '/';
	out[n] = '\0';
	return out;
}

/*
 * $PWD keeps the symlinks the user went through, which is what Claude Code
 * records; it is trusted only while it still names the current directory.
 */
static char *logical_cwd(void)
{
	struct stat a, b;
	const char *pwd;

	pwd = getenv("PWD");
	if (pwd != NULL && pwd[0] == '/' && stat(pwd, &a) == 0 &&
	    stat(".", &b) == 0 && a.st_dev == b.st_dev && a.st_ino == b.st_ino)
		return xstrdup(pwd);
	return xgetcwd();
}

char *path_logical(const char *path)
{
	char *cwd, *joined, *out;

	if (path[0] == '/')
		return path_normalize(path);
	cwd = logical_cwd();
	if (cwd == NULL)
		return NULL;
	joined = xjoin(cwd, path);
	out = path_normalize(joined);
	free(cwd);
	free(joined);
	return out;
}

/*
 * realpath of the longest existing ancestor with the rest appended, so a
 * path that does not exist yet still resolves the symlinks above it.
 */
char *path_physical(const char *path)
{
	char *work, *tail, *real, *joined, *out, *slash, *t;
	size_t len;

	if (path[0] == '/') {
		work = xstrdup(path);
	} else {
		t = xgetcwd();
		if (t == NULL)
			return NULL;
		work = xjoin(t, path);
		free(t);
	}
	tail = xstrdup("");
	while ((real = realpath(work, NULL)) == NULL) {
		if (errno != ENOENT && errno != ENOTDIR) {
			free(work);
			free(tail);
			return NULL;
		}
		len = strlen(work);
		while (len > 1 && work[len - 1] == '/')
			work[--len] = '\0';
		slash = strrchr(work, '/');
		t = xjoin(slash + 1, tail);
		free(tail);
		tail = t;
		slash[slash == work ? 1 : 0] = '\0';
	}
	joined = xjoin(real, tail);
	out = path_normalize(joined);
	free(work);
	free(tail);
	free(real);
	free(joined);
	return out;
}

/* True when path is prefix itself or lies below it: "repo" never matches "repo2". */
int path_has_prefix(const char *path, const char *prefix)
{
	size_t n;

	n = strlen(prefix);
	while (n > 0 && prefix[n - 1] == '/')
		n--;
	if (strncmp(path, prefix, n) != 0)
		return 0;
	return path[n] == '\0' || path[n] == '/';
}

/*
 * value moved from old to new: new plus the rest of value, when value is old
 * or lies below it (only below it with below_only), NULL otherwise.
 */
char *path_move(const char *value, const char *old, const char *new,
    int below_only)
{
	size_t n, m;
	char *out;

	if (!path_has_prefix(value, old))
		return NULL;
	n = strlen(old);
	while (n > 0 && old[n - 1] == '/')
		n--;
	if (value[n] == '\0' && below_only)
		return NULL;
	m = strlen(new);
	while (m > 0 && new[m - 1] == '/')
		m--;
	if (m == 0 && value[n] == '\0')
		return xstrdup("/");
	out = xmalloc(m + strlen(value + n) + 1);
	memcpy(out, new, m);
	strcpy(out + m, value + n);
	return out;
}

/* $HOME, or the password database entry when it is not set. */
char *path_home(void)
{
	const char *home;
	struct passwd *pw;

	home = getenv("HOME");
	if (home != NULL && home[0] == '/')
		return xstrdup(home);
	pw = getpwuid(getuid());
	if (pw != NULL && pw->pw_dir != NULL && pw->pw_dir[0] == '/')
		return xstrdup(pw->pw_dir);
	return NULL;
}

/* path for people: "~" in place of the home directory. */
char *path_tilde(const char *path, const char *home)
{
	if (home == NULL || strcmp(home, "/") == 0 ||
	    !path_has_prefix(path, home))
		return xstrdup(path);
	return path_move(path, home, "~", 0);
}

/* The last component; "/" for the root. */
char *path_base(const char *path)
{
	const char *end, *start;
	char *out;

	end = path + strlen(path);
	while (end > path + 1 && end[-1] == '/')
		end--;
	for (start = end; start > path && start[-1] != '/'; start--)
		;
	if (start == end)
		return xstrdup("/");
	out = xmalloc((size_t)(end - start) + 1);
	memcpy(out, start, (size_t)(end - start));
	out[end - start] = '\0';
	return out;
}

/* Everything before the last component; "/" for a path right below the root. */
char *path_dir(const char *path)
{
	char *out, *slash;
	size_t len;

	out = xstrdup(path);
	len = strlen(out);
	while (len > 1 && out[len - 1] == '/')
		out[--len] = '\0';
	slash = strrchr(out, '/');
	if (slash == NULL) {
		free(out);
		return xstrdup(".");
	}
	slash[slash == out ? 1 : 0] = '\0';
	return out;
}
